#include <cstdio>
#include <cstdlib>
#include <map>
#include "engine/gameplay/force_editor_session.hpp"
#include "tests/unit/force_inventory_fixture.hpp"
namespace {
using namespace gf;unsigned checks=0;void check(bool x,const char* why){++checks;if(!x){std::fprintf(stderr,"warehouse tools: %s\n",why);std::abort();}}
struct Save final:ISaveBackend {std::map<u32,std::vector<u8>> slots;bool fail=false;unsigned writes=0;bool load(u32 slot,std::vector<u8>& out)override{if(!slots.contains(slot))return false;out=slots[slot];return true;}SaveReadStatus read_slot(u32 slot,std::vector<u8>& out)override{return load(slot,out)?SaveReadStatus::Loaded:SaveReadStatus::Missing;}bool store(u32 slot,const u8* p,std::size_t n)override{if(fail)return false;slots[slot]={p,p+n};++writes;return true;}bool erase(u32 slot)override{return slots.erase(slot)!=0;}};
ForceSpecificationCatalog spec(const ForceCatalog& catalog){std::vector<u8> b(26+138*catalog.entries().size());store_be32(b.data(),0x47465344);store_be32(b.data()+4,1);store_be32(b.data()+8,catalog.fingerprint());store_be16(b.data()+12,u16(catalog.entries().size()));store_be16(b.data()+14,138);for(unsigned i=0;i<catalog.entries().size();++i){const auto at=26+i*138;store_be16(b.data()+at,catalog.entries()[i].model);store_be16(b.data()+at+2,catalog.entries()[i].number);b[at+8]=255;for(unsigned k=8;k<13;++k)b[at+5+k]=255;for(unsigned k=0;k<60;++k)store_be16(b.data()+at+18+k*2,100);}ForceSpecificationCatalog out;std::string error;check(out.load({b.data(),b.size()},catalog,&error),"owned spec");return out;}
}
int main(){using namespace gf;auto catalog=force_inventory_fixture::catalog();auto data=spec(catalog);ForceInventory owner;check(owner.create(catalog,false),"inventory");const CheatSettings on{true,true};Save save;ForceInventoryStore store(save);check(store.load(catalog,&owner)==ForceInventoryLoad::Missing,"missing save permits native write");
    const auto revision=owner.revision();check(owner.pick_warehouse({},0x1001,0)==ForceChange::Invalid&&owner.revision()==revision,"off cannot add");check(owner.pick_warehouse(on,0x1001,6)==ForceChange::Invalid,"variant bounds");
    check(owner.pick_warehouse(on,0x1001,2)==ForceChange::Applied&&owner.pick_warehouse(on,0x1001,0)==ForceChange::Applied&&owner.pick_warehouse(on,0x1001,0)==ForceChange::Applied,"nonconsuming picker creates real instances");check(owner.state()->warehouse_count==3&&owner.state()->box_count==0&&owner.state()->warehouse[1].acquired!=owner.state()->warehouse[2].acquired,"distinct real warehouse identity");
    auto state=std::make_unique<ForceInventoryState>(*owner.state());state->warehouse[0].experience=999;state->warehouse[1].experience=10;state->warehouse[2].experience=20;check(owner.load_state(catalog,*state),"experience fixture");WarehouseTools tools;WarehouseToolEvent event;check(tools.open(owner,data,on)&&tools.models().size()==1&&tools.step(owner,0,0x100,0,&event),"one model group");check(tools.instances().size()==3&&tools.instances()[0]==2&&tools.instances()[1]==1&&tools.instances()[2]==0,"normal before variant; EXP descending within");
    check(tools.step(owner,0,0x100,0,&event)&&tools.slot()==2&&tools.page()==WarehouseToolPage::Actions,"actual instance storage popup");while(tools.wait_updates()){check(tools.step(owner,0,0,0,&event),"popup opening wait");}const auto before_adjust=owner.revision();check(tools.step(owner,0,0,1,&event)&&owner.revision()==before_adjust&&!owner.state()->warehouse[2].edits.modified,"warehouse popup cannot edit Borg fields");check(owner.state()->warehouse[0].edits==BorgEdits{}&&owner.state()->warehouse[1].edits==BorgEdits{},"neighbors untouched");
    auto rev=owner.revision();check(owner.edit_borg({},true,2,rev,BorgEditField::HP,200)==ForceChange::Invalid&&owner.edit_borg(on,true,2,rev-1,BorgEditField::HP,200)==ForceChange::Invalid,"off/stale edits refuse");
    check(owner.edit_borg(on,true,2,rev,BorgEditField::Cost,321)==ForceChange::Applied,"cost override");for(auto [field,value]:std::array<std::pair<BorgEditField,int>,7>{{{BorgEditField::HP,234},{BorgEditField::DEF,7},{BorgEditField::SHT,8},{BorgEditField::ATK,9},{BorgEditField::SPD,10},{BorgEditField::BAmmo,12},{BorgEditField::XAmmo,34}}})check(owner.edit_borg(on,true,2,owner.revision(),field,value)==ForceChange::Applied,"all stat/ammo overrides");
    check(owner.edit_borg(on,true,2,owner.revision(),BorgEditField::HP,0)==ForceChange::Invalid&&owner.edit_borg(on,true,2,owner.revision(),BorgEditField::SPD,11)==ForceChange::Invalid,"represented domains");
    s16 box=-1;check(owner.from_warehouse(2,&box)==ForceChange::Applied&&box==0&&owner.state()->box[0].value.edits.modified,"transfer retains provenance");check(owner.place(19,29,0)==ForceChange::Applied&&owner.place(0,0,0)==ForceChange::Applied&&owner.state()->forces[19].cost==321&&owner.state()->forces[0].cost==321,"shared membership and force20 costs");
    check(owner.edit_borg(on,false,0,owner.revision(),BorgEditField::Cost,322)==ForceChange::Applied&&owner.state()->forces[0].cost==322&&owner.state()->forces[19].cost==322,"shared costs refresh");ForceBattleRoster roster;check(!owner.battle_roster(19,-1,ForceCostMode::Full,&roster)&&roster.members().empty(),"default roster excludes edited Borgs");
    check(store.write(owner),"native v2 save");ForceInventory restored;ForceInventoryStore reload(save);check(reload.load(catalog,&restored)==ForceInventoryLoad::Loaded&&restored.state()->box[0].value.edits==owner.state()->box[0].value.edits&&restored.state()->forces[19].cost==322,"extension roundtrip including force20");
    auto images=std::make_unique<ForceInventoryImages>();check(!force_inventory_encode(*owner.state(),catalog,images.get()),"raw codec cannot silently lose edits");check(restored.edit_borg(on,false,0,restored.revision(),BorgEditField::Cost,-1)==ForceChange::Applied&&restored.state()->box[0].value.edits.modified,"reset value retains sticky flag");
    check(restored.to_warehouse(0)==ForceChange::Applied&&restored.state()->forces[19].count==0&&restored.state()->warehouse[2].edits.modified,"return to warehouse preserves identity/retire membership");
    CheatSettingsStore settings(save);CheatSettings loaded;check(settings.load(&loaded)==CheatSettingsLoad::Missing&&loaded==CheatSettings{}&&settings.write(on),"cheats default off and save");check(settings.load(&loaded)==CheatSettingsLoad::Loaded&&loaded==on,"settings handoff persistence");save.fail=true;check(!settings.write({})&&!store.write(owner),"failed writes reported");save.fail=false;
    check(settings.load(&loaded)==CheatSettingsLoad::Loaded&&loaded==on,"failed settings write retains prior record");
    ForceInventory clean;check(clean.create(catalog)&&store.write(clean)&&reload.load(catalog,&restored)==ForceInventoryLoad::Loaded&&!restored.state()->box[0].value.edits.modified,"unmodified v1 save remains readable");
    auto full=std::make_unique<ForceInventoryState>(*clean.state());for(auto& b:full->warehouse){b={};b.model=0x1001;}full->warehouse_count=kWarehouseBorgs;check(clean.load_state(catalog,*full),"full warehouse fixture");rev=clean.revision();check(clean.pick_warehouse(on,0x1002,0)==ForceChange::Full&&clean.revision()==rev,"full add is atomic");
    std::printf("warehouse tools/save/provenance: %u checks PASS\n",checks);
}
